                elif i == 0:
                    C[j][i] = C[j - 1][i] + times[j][i]
                else:
                    C[j][i] = max(C[j - 1][i], C[j][i - 1]) + times[j][i]
        return C[-1][-1]
    # NEH heuristic
    if n == 2:
        seq = jobs[:]
    else:
        seq = [jobs[0], jobs[1]]
        for k in range(2, n):
            next_job = jobs[k]
            best_makespan = math.inf
            best_pos = 0
